import React, { useEffect, useState } from "react";
import Store from './store';
import styles from './index.module.less';
import { Button, Collapse, Divider, Drawer, Empty, Link, List, Message, Popover, Result, Space, Spin, Tag, Tooltip, Tree, TreeSelect } from "@arco-design/web-react";
import { useObserver } from "mobx-react-lite";
import i18next, { t } from "i18next";
import { IfrmaeWindowProps, IfrmaeAppProps } from "@/types/iframe";
import AppTheme from "@/components/Settings/theme";
import { IconMoonFill, IconSunFill } from "@arco-design/web-react/icon";
import locales from "@code/locales";
import config from "config";
import app from "@/store/app";
import { useHistory } from "react-router-dom";



export const settingStore = Store;
const win: IfrmaeWindowProps = window as any;

// const { app }: IfrmaeAppProps = window as any;

interface SettingProps {
    store: Store;
}


const Settings = ({ store }: SettingProps) => {


    const iframeWindow: any = store.iframeRef.current?.contentWindow;

    useEffect(() => {
        // @ts-ignore
        const language = window.language;

        if(language){
            locales.options = locales.options.filter((o) => app.extraInfo.languageKeys.includes(o.value));
            locales.changeLang = async (lng) => {
                const translations = language.getLanguageData(lng);
                i18next.addResourceBundle(lng, 'translation', translations, true, true);
                i18next.changeLanguage(lng);
                locales.setLang(lng);
            }
            locales.changeLang(locales.lang);
        }
    }, [])

    const history2 = useHistory();

    useEffect(() => {
        if(iframeWindow){
            const updatePathname = () => {
                const path = iframeWindow.location.hash;
                store.setPathname(path)
                history2.push(path.slice(1))    // 同步当前线上路由
                if(path.startsWith(`#${config.admin_path}`)){
                    if(win.dev){
                        win.dev.autoLogin()
                    }
                }
            }
            updatePathname();
            iframeWindow.addEventListener('hashchange', function() {
                updatePathname()
            });
        }
    },[iframeWindow])

    return useObserver(() => {

        const { login_path, admin_path } = app.extraInfo.configuration;

        return (
            <div className={styles.header}>
                <Space>
                    <div>
                        切换路由
                        <Popover
                            position='bl'
                            trigger="click"
                            content={(
                                <div className="min-w-80 h-80 overflow-y-auto">
                                    <Tree
                                        blockNode
                                        className="w-full"
                                        autoExpandParent
                                        fieldNames={{
                                            key: "path",
                                            title: "name"
                                        }}
                                        defaultSelectedKeys={[store.pathname]}
                                        onSelect={(keys, extra) => {
                                            const { dataRef: item }: any = extra.node.props
                                            if(win.utils){
                                                const { history } = win.utils
                                                history.push(`${keys[0]}`);
                                            }
                                        }}
                                        treeData={win? win.dev.routes : []}
                                        renderTitle={({ title, dataRef, ...props }) => {
                                            return `${i18next.t(title as string)}(${dataRef.path})`
                                        }}
                                    />
                                    <Divider style={{ margin: "0 20px" }}>后台路由</Divider>
                                    <Tree
                                        blockNode
                                        autoExpandParent
                                        fieldNames={{
                                            key: "path",
                                            title: "name"
                                        }}
                                        defaultSelectedKeys={[store.pathname.replace('/admin', '')]}
                                        onSelect={(keys, extra) => {
                                            const { dataRef: item }: any = extra.node.props
                                            if(win.utils){
                                                const { history } = win.utils
                                                if(item.path == login_path){
                                                    history.push(`${keys[0]}`);
                                                }else {
                                                    history.push(`${admin_path}${keys[0]}`);
                                                }
                                            }
                                        }}
                                        treeData={[
                                            {
                                                path: login_path,
                                                name: "登陆页面",
                                            },
                                            ...win.dev.adminMenu,
                                        ]}
                                        renderTitle={({ title, dataRef, ...props }) => {
                                            return `${i18next.t(title as string)}(${dataRef.path})`
                                        }}
                                    />
                                </div>
                            )}
                        >
                            <Button type="text" size="small" >
                                URL：{store.pathname}
                            </Button>
                        </Popover>
                    </div>
                    <Popover
                        position='bl'
                        trigger="click"
                        style={{ maxWidth: 900 }}
                        content={(
                            <div style={{ width: 800 }}>
                                <AppTheme />
                            </div>
                        )}
                    >
                        <Button type="default" size="small" >
                            切换主题
                        </Button>
                    </Popover>
                </Space>
                <Space>
                    <Button
                        size="small"
                        onClick={() => {
                            store.setIsReady(false);
                            setTimeout(() => {
                                store.setIsReady(true);
                            },300)
                        }}
                    >刷新</Button>
                </Space>
            </div>
        )

    })

}


export default Settings;